import{Utils}from"../utils.min.js?v=1.0.0";let __=wp.i18n.__,Tiered_Shipping={template:"#shipflex-tiered-shipping-component",props:{shippingData:{default:null,type:[null,Object]},number:{default:0,type:Number},calculateBasis:{default:null,type:[null,String]}},emits:["update"],data(){return{...shipflex_admin.tiered_shipping_models,...this.shippingData}},computed:{variation_no(){return this.number+1},metric_label(){return this.$root.calculation_metric_label(this.calculateBasis)},metric_label_lower(){return this.$root.calculation_metric_label(this.calculateBasis,"lowercase")}},watch:{calculateBasis(t){("subtotal"==t&&"cost_per_unit"==this.shipping_cost_type||"subtotal"!=t&&"percentage"==this.shipping_cost_type)&&(this.shipping_cost_type="fixed_cost")}},methods:{add_condition_group(){Array.isArray(this.condition_groups)||(this.condition_groups=[]),this.condition_groups.push({id:Utils.generate_uuid()})},delete_condition_group(t){this.condition_groups.splice(t,1)}}};export default Tiered_Shipping;